using System.Security.Cryptography;
using Jindan.Contracts;
using Jindan.Core;
using static Jindan.Core.DomainRules;
namespace Jindan.Infrastructure;

public sealed partial class LocalWorkspace
{
    public bool IsInitialized => _state.Users.Count > 0;
    static void Password(string password) => Require(password is not null && password.Length is >= 10 and <= 1024, "PASSWORD_POLICY", "Use a local password with at least ten characters.");
    static string Name(string name) { Require(!string.IsNullOrWhiteSpace(name) && name.Trim().Length <= 100, "VALIDATION", "A display name of at most100 characters is required."); return name.Trim(); }
    static void SetPassword(StoredUser user, string password) { Password(password); var salt = RandomNumberGenerator.GetBytes(32); user.Salt = Convert.ToBase64String(salt); user.Iterations = 210000; user.PasswordHash = Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(password, salt, user.Iterations, HashAlgorithmName.SHA256, 32)); }
    static bool VerifyPassword(StoredUser user, string password) { try { if (password is null || password.Length > 1024 || user.Iterations < 100000 || user.Iterations > 2000000) return false; var actual = Rfc2898DeriveBytes.Pbkdf2(password, Convert.FromBase64String(user.Salt), user.Iterations, HashAlgorithmName.SHA256, 32); return CryptographicOperations.FixedTimeEquals(actual, Convert.FromBase64String(user.PasswordHash)); } catch (FormatException) { return false; } }
    Identity Session(StoredUser user) { var actor = new Identity(user.Id, user.DisplayName, user.Role, Array.AsReadOnly(user.ProjectIds.ToArray())); _sessions.Add(actor, user.Id); return actor; }
    static UserInfo PublicUser(StoredUser user) => new(user.Id, user.DisplayName, user.Role, user.ProjectIds.ToArray(), user.Disabled) { Position = user.Position };
    public Task<Identity> BootstrapAsync(string displayName, string password, bool explicitLocalWorkspace, CancellationToken ct = default) => Locked(() => { Require(explicitLocalWorkspace, "CONFIRMATION", "Explicit local workspace setup is required."); Require(!IsInitialized, "INITIALIZED", "The local workspace already has an identity."); var user = new StoredUser { Id = Guid.NewGuid().ToString("N"), DisplayName = Name(displayName), Role = "admin" }; SetPassword(user, password); var next = Clone(); next.Users.Add(user); Commit(next, ct); return Session(user); }, ct);
    public Task<Identity> LoginAsync(string displayName, string password, CancellationToken ct = default) => Locked(() => { var name = Name(displayName); var user = _state.Users.SingleOrDefault(u => string.Equals(u.DisplayName, name, StringComparison.OrdinalIgnoreCase)); Require(user is not null && !user.Disabled && VerifyPassword(user, password), "AUTH_FAILED", "The local credentials are invalid or disabled."); return Session(user!); }, ct);
    public Task<IReadOnlyList<UserInfo>> ListAsync(Identity actor, CancellationToken ct = default) => Locked<IReadOnlyList<UserInfo>>(() => { Admin(Actor(actor)); return _state.Users.Select(PublicUser).ToArray(); }, ct);
    public Task<UserInfo> SaveUserAsync(Identity actor, string? id, string name, string role, string[] projects, bool disabled, string? newPassword, CancellationToken ct = default) => SaveUserProfileCoreAsync(actor, id, name, null, role, projects, disabled, newPassword, ct); public Task<UserInfo> SaveUserProfileAsync(Identity actor, string? id, string name, string position, string role, string[] projects, bool disabled, string? newPassword, CancellationToken ct = default) => SaveUserProfileCoreAsync(actor, id, name, position, role, projects, disabled, newPassword, ct); private Task<UserInfo> SaveUserProfileCoreAsync(Identity actor, string? id, string name, string? position, string role, string[] projects, bool disabled, string? newPassword, CancellationToken ct) => Locked(() => { var admin = Actor(actor); Admin(admin); var display = Name(name); Require(position is null || position.Length <= 100, "VALIDATION", "Position must fit100characters."); Require(id != admin.Id || !disabled, "SELF_DISABLE", "An administrator cannot disable the active local account."); Require(role is "admin" or "editor" or "viewer", "VALIDATION", "The local role is invalid."); Require(projects is not null && projects.Length <= 10000 && projects.Distinct().Count() == projects.Length && projects.All(p => _state.Records.Any(r => IsProject(r.Kind) && r.Id == p && !r.Deleted)), "PROJECT_SCOPE", "All assigned projects must exist and be unique."); Require(!_state.Users.Any(u => u.Id != id && string.Equals(u.DisplayName, display, StringComparison.OrdinalIgnoreCase)), "DUPLICATE_USER", "The local display name is already used."); var next = Clone(); StoredUser user; if (id is null) { Require(newPassword is not null, "PASSWORD_POLICY", "A password is required for a new local user."); user = new() { Id = Guid.NewGuid().ToString("N") }; next.Users.Add(user); } else { user = next.Users.SingleOrDefault(u => u.Id == id)!; Require(user is not null, "NOT_FOUND", "Local user not found."); } user!.DisplayName = display; if (position is not null) user.Position = position; user.Role = role; user.ProjectIds = projects!.ToArray(); user.Disabled = disabled; if (newPassword is not null) SetPassword(user, newPassword); Require(next.Users.Any(u => u.Role == "admin" && !u.Disabled), "LAST_ADMIN", "The last enabled administrator must remain available."); Commit(next, ct); return PublicUser(user); }, ct);
    public async Task ChangePasswordAsync(Identity actor, string oldPassword, string newPassword, CancellationToken ct = default) { await Locked(() => { var user = Actor(actor); Require(VerifyPassword(user, oldPassword), "AUTH_FAILED", "The existing local password is invalid."); var next = Clone(); SetPassword(next.Users.Single(u => u.Id == user.Id), newPassword); Commit(next, ct); foreach (var session in _sessions.Where(p => p.Value == user.Id && !ReferenceEquals(p.Key, actor)).Select(p => p.Key).ToArray()) _sessions.Remove(session); return true; }, ct); }
}
